<script setup>
import { computed, ref, shallowRef } from 'vue'
import { osmToGeoJson } from './osmToGeoJson.js'
import { downloadFile } from '../shared/download.js'

const source = shallowRef(null)
const loading = ref(false)
const exporting = ref(false)
const fileError = ref('')
const exportError = ref('')
const result = ref(null)
const busy = computed(() => loading.value || exporting.value)

async function loadOsm(file) {
  source.value = null
  result.value = null
  fileError.value = ''
  exportError.value = ''
  const selectedFile = Array.isArray(file) ? file[0] : file
  if (!selectedFile) return
  loading.value = true
  try {
    source.value = { name: selectedFile.name, text: await selectedFile.text() }
  } catch (error) {
    fileError.value = `Could not read OSM: ${error.message}`
  } finally {
    loading.value = false
  }
}

async function exportGeoJson() {
  if (!source.value || busy.value) return
  result.value = null
  exportError.value = ''
  exporting.value = true
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    const collection = osmToGeoJson(source.value.text)
    const filename = source.value.name.replace(/\.[^.]+$/, '') + '_buildings.geojson'
    downloadFile(JSON.stringify(collection), filename)
    result.value = { features: collection.features.length, filename }
  } catch (error) {
    exportError.value = `Could not convert OSM: ${error.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form nhận OSM/XML và xuất GeoJSON công trình; VaAlert bên dưới hiển thị lỗi hoặc số feature đã xuất. -->
  <section>
    <h1 class="page-title">OSM → GeoJSON</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportGeoJson">
          <VaFileUpload
            id="osm-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="OSM file"
            file-types=".osm,.xml,application/xml,text/xml"
            :disabled="busy"
            @update:modelValue="loadOsm"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
          <VaAlert v-if="fileError" color="danger" role="alert">{{ fileError }}</VaAlert>
          <VaButton type="submit" color="primary" :loading="exporting" :disabled="!source || busy">
            Export GeoJSON
          </VaButton>
        </VaForm>
        <VaAlert v-if="exportError" color="danger" class="mt-4" role="alert">
          {{ exportError }}
        </VaAlert>
        <VaAlert
          v-if="result"
          :color="result.features ? 'success' : 'warning'"
          class="mt-4"
          role="status"
          data-testid="osm-result"
        >
          {{ result.features }} building features exported.
          <span v-if="!result.features">The exported FeatureCollection is empty.</span>
          Downloaded: {{ result.filename }}.
        </VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
