import osmtogeojson from 'osmtogeojson'

/**
 * Parse OSM XML and convert its nodes, ways and multipolygon relations locally.
 * Keep features with a building tag, including building="no", and flatten only
 * their tags into properties. OSM identifiers remain in feature.id.
 * Reject invalid XML, invalid node coordinates and incomplete building geometry.
 * A valid file without buildings returns an empty FeatureCollection.
 *
 * Input:
 *   '<osm version="0.6"><node id="1" lon="10" lat="20">'
 *   + '<tag k="building" v="yes"/><tag k="name" v="Office"/></node></osm>'
 * Output:
 *   { type: 'FeatureCollection', features: [{ type: 'Feature', id: 'node/1',
 *     properties: { building: 'yes', name: 'Office' },
 *     geometry: { type: 'Point', coordinates: [10, 20] } }] }
 * Closed building ways produce Polygons; multipolygon inner members become holes.
 */
// shortcut: the XML DOM and converted features stay in memory; use a worker if real OSM inputs freeze the UI.
export function osmToGeoJson(text) {
  const xml = new DOMParser().parseFromString(text.replace(/^\uFEFF/, ''), 'text/xml')
  if (xml.getElementsByTagName('parsererror').length || xml.documentElement?.localName !== 'osm') {
    throw new Error('File must contain valid OSM XML with an osm root element.')
  }
  const nodes = Array.from(xml.getElementsByTagName('node'))
  const nodeIds = new Set(nodes.map((node) => node.getAttribute('id')))
  for (const node of nodes) {
    const lon = node.getAttribute('lon')
    const lat = node.getAttribute('lat')
    if (
      !lon?.trim() ||
      !lat?.trim() ||
      !Number.isFinite(Number(lon)) ||
      !Number.isFinite(Number(lat)) ||
      Math.abs(Number(lon)) > 180 ||
      Math.abs(Number(lat)) > 90
    ) {
      throw new Error(`OSM node ${node.getAttribute('id')} has invalid longitude/latitude.`)
    }
  }
  const ways = Array.from(xml.getElementsByTagName('way'))
  const wayIds = new Set(ways.map((way) => way.getAttribute('id')))
  for (const way of ways) {
    for (const reference of Array.from(way.getElementsByTagName('nd'))) {
      if (!nodeIds.has(reference.getAttribute('ref'))) {
        throw new Error(`OSM way ${way.getAttribute('id')} refers to a missing node.`)
      }
    }
  }
  for (const relation of Array.from(xml.getElementsByTagName('relation'))) {
    const tags = Array.from(relation.getElementsByTagName('tag'))
    if (!tags.some((tag) => tag.getAttribute('k') === 'building')) continue
    for (const member of Array.from(relation.getElementsByTagName('member'))) {
      if (member.getAttribute('type') === 'way' && !wayIds.has(member.getAttribute('ref'))) {
        throw new Error(`OSM building relation ${relation.getAttribute('id')} refers to a missing way.`)
      }
    }
  }
  const collection = osmtogeojson(xml, { flatProperties: false })
  const buildings = collection.features.filter((feature) => Object.hasOwn(feature.properties.tags, 'building'))
  if (buildings.some((feature) => feature.properties.tainted)) {
    throw new Error('OSM building geometry is incomplete; include its referenced nodes and ways.')
  }
  collection.features = buildings.map((feature) => ({
    ...feature,
    properties: { ...feature.properties.tags },
  }))
  const bounds = xml.getElementsByTagName('bounds')[0]
  if (bounds) {
    const values = ['minlon', 'minlat', 'maxlon', 'maxlat'].map((key) => bounds.getAttribute(key))
    const bbox = values.map(Number)
    if (
      values.every((value) => value?.trim()) &&
      bbox.every(Number.isFinite) &&
      Math.abs(bbox[0]) <= 180 &&
      Math.abs(bbox[2]) <= 180 &&
      Math.abs(bbox[1]) <= 90 &&
      Math.abs(bbox[3]) <= 90 &&
      bbox[0] <= bbox[2] &&
      bbox[1] <= bbox[3]
    )
      collection.bbox = bbox
  }
  return collection
}
